insert into initiatives (id, status_code, slug, submission_kind, card, title, summary, domains, institution_type, stage, cross_topics, innovation_kind, sectors, trl, ip_status, institution_id, teryt, radar, signal, status, published, nominations_count, synthetic, created_at, updated_at) values ('64680294-3c09-5e0d-aff0-e103173286ac', 'RAD-WH27', 'robotyka-wiejska-korczyna', 'own', '{"title": "Pracownia robotyki dla szkół z małych wsi", "summary": "Jedna szkoła kupiła zestawy robotów i co tydzień wozi je do trzech sąsiednich szkół.", "problem": "Uczniowie z małych szkół nie mają dostępu do zajęć z robotyki i programowania, a dojazd do miasta na kółka trwa godzinę.", "solution": "Jedna szkoła kupiła zestawy robotów i co tydzień wozi je do trzech sąsiednich szkół. Zajęcia prowadzi nauczyciel informatyki z uczniami starszych klas jako asystentami.", "effects": "W zajęciach bierze udział 72 uczniów z czterech szkół. Dwie drużyny startowały w wojewódzkim konkursie robotyki.", "beneficiaries": "uczniowie klas 4–8 z małych szkół wiejskich", "domains": ["edukacja", "cyfryzacja"], "institutionType": "szkola_podstawowa", "stage": "przeniesiona", "cross": ["obszary_wiejskie", "mlodzi"], "innovationKind": "edukacyjna", "sectors": ["ict"], "trl": null, "ipStatus": null, "creatorRoles": ["nauczyciel", "uczen"], "municipality": "Korczyna", "keywords": ["robotyka", "programowanie", "szkoła wiejska", "uczeń", "zajęcia pozalekcyjne", "kompetencje cyfrowe"], "clarity": 0.73, "followUps": []}'::jsonb, 'Pracownia robotyki dla szkół z małych wsi', 'Jedna szkoła kupiła zestawy robotów i co tydzień wozi je do trzech sąsiednich szkół.', array['edukacja','cyfryzacja']::text[], 'szkola_podstawowa', 'przeniesiona', array['obszary_wiejskie','mlodzi']::text[], 'edukacyjna', array['ict']::text[], null, null, '8984ca59-d085-5948-89ab-b8760b6a88ed', '1807052', '{"dimensions": {"przenaszalnosc": {"score": 4, "why": "Wystarczy zestaw robotów i nauczyciel, który dojeżdża do sąsiednich szkół.", "basis":